-- Resources: Log tutorial guides (docs/resources-design.md slice 5).
-- Three gaps in the tool's guide set: the content library, the merged
-- rundown-builder/host-console screen, and the NPR/weather panels --
-- alongside the two guides seeded with Resources itself (read-a-clock,
-- schedule-a-program). NPR/weather have no dedicated screen key in
-- lib/resources/screens.ts (same as Underwriting's dashboard) -- Help still
-- lists this guide for the tool, just not scoped to one screen.
-- Content only. Upserts on slug; guarded by edited_since_release.

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'log-content-library', 'guide'::public.rc_kind, 'Building the content library', 'Add news, promos, and other spots to the library, or import WUWF''s existing DAD cut library in bulk.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Any tool member can add to it, not just producers."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a content item"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the library, optionally filter by content type or approval status, then select "},{"type":"text","text":"+ New content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a title, content type, summary, script, expected duration, and effective dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add its components"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the item''s page, expand "},{"type":"text","text":"Add a component","marks":[{"type":"bold"}]},{"type":"text","text":" — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select "},{"type":"text","text":"Add component","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A required component counts toward the item''s total time; an optional one doesn''t."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approve it"}]},{"type":"paragraph","content":[{"type":"text","text":"An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import WUWF''s DAD cut library"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview import","marks":[{"type":"bold"}]},{"type":"text","text":" to see the plan: new items, updates to existing ones, and anything it couldn''t place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":" to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There''s no audio upload here. WUWF''s playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{log.library}'::text[], 10, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'log'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'log-daily-rundown-and-console', 'guide'::public.rc_kind, 'Running the daily rundown and host console', 'Generate a rundown, fill its breaks, and run it live — one screen for building and broadcasting.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A rundown''s screen does double duty: build it ahead of time, then run the same screen live once you start the broadcast."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Generate and fill"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Today screen, select "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":" next to a program that doesn''t have a rundown yet for that date."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open it. Hover the thin line between items in a break to fill it — search the eligible content library, add today''s weather, or create a one-off live read right there."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Go live"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Start broadcast","marks":[{"type":"bold"}]},{"type":"text","text":" in the sidebar. The current break is highlighted, and the mid-broadcast controls appear on every unconfirmed item across the whole rundown."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"During the broadcast"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On an underwriting credit, confirm it with "},{"type":"text","text":"Yes, aired","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"No — flag it","marks":[{"type":"bold"}]},{"type":"text","text":" (choosing a reason). Ordinary content has no aired/missed confirmation — only a credit carries that obligation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move any item with its "},{"type":"text","text":"⋮","marks":[{"type":"bold"}]},{"type":"text","text":" menu, or drag it to a different break."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Wrap up"}]},{"type":"paragraph","content":[{"type":"text","text":"The sidebar''s Wrap-up panel lists anything unresolved. Optionally attest or mark items aired in bulk, then select "},{"type":"text","text":"Submit rundown","marks":[{"type":"bold"}]},{"type":"text","text":" — a checkpoint, not a lock. A correction after submission works exactly the same as before it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aired, missed, and move actions are queued on your device and sent once you''re back online — a dropped connection doesn''t lose them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding content to a break needs a live connection, since it''s a request to the server rather than a queued action."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{log.rundown}'::text[], 40, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'log'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'log-npr-and-weather', 'guide'::public.rc_kind, 'NPR and weather panels', 'See a program''s next NPR stories, and the current forecast, without leaving Log.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two integrations refresh themselves as you read them, and can be forced to refresh by hand."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"NPR"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the NPR screen, choose a program and a show date, then select "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The table lists each story''s estimated air time (marked with “~”, since NPR doesn''t supply exact times), title, teaser, and length."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" to pull the latest episode data."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weather"}]},{"type":"paragraph","content":[{"type":"text","text":"The weather screen shows the current forecast: any hazards, a short outlook, live-read and condensed text for on air, and the underlying details. Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" to force an update."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Both screens show a “Stale” badge once their cached data is older than its normal refresh window — Refresh is a manual option, not something you need to do routinely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A fetch failure shows as a plain message, with whatever was last successfully read still on screen. Neither screen goes blank because of a temporary outage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NPR''s estimated times need a rundown to already exist for that program and date — without one, the table has nothing to anchor its estimates to."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{}'::text[], 50, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'log'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

